import{Rt as e,dt as t,mt as n,n as r}from"./chunks/framework.BkIgthgQ.js";var i=JSON.parse(`{"title":"反向代理与 TLS","description":"公网只暴露客户端平面；管理面绑定本机或内网。证书可在平面 YAML 或由反代终止。","frontmatter":{"title":"反向代理与 TLS","description":"公网只暴露客户端平面；管理面绑定本机或内网。证书可在平面 YAML 或由反代终止。"},"headers":[],"relativePath":"guide/config/reverse-proxy.md","filePath":"guide/config/reverse-proxy.md","lastUpdated":1790057721000}`),a={name:`guide/config/reverse-proxy.md`};function o(r,i,a,o,s,c){return e(),t(`div`,null,[...i[0]||=[n(`<h1 id="反向代理与-tls" tabindex="-1">反向代理与 TLS <a class="header-anchor" href="#反向代理与-tls" aria-label="Permalink to “反向代理与 TLS”">​</a></h1><p>建议：公网只反代客户端平面（<code>:8080</code>）。管理平面绑定 <code>127.0.0.1</code> 或仅内网，再经 VPN / SSH / 内网反代访问。</p><p>TLS 有两种做法（可混用两个平面）：</p><ol><li>平面 YAML 的 <code>tls_cert</code> + <code>tls_key</code>（两行同时非空）。</li><li>反代终止 TLS，后端明文；此时必须配置该平面 <code>trusted_proxies</code>，否则 <code>X-Forwarded-For</code> 不会被信任。</li></ol><p>空 <code>trusted_proxies</code> 调用 <code>SetTrustedProxies(nil)</code>，<strong>不会</strong>走 Gin 默认「信任全部」。</p><p>生产管理平面会把 <code>/api/v1/projects/**</code> 反代到本进程客户端平面，供控制台预览。管理平面 <code>GET /</code> 托管管理台 SPA；文档站应单独部署，否则与 SPA 抢路由。</p>`,6)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};